for (let i = 0; i < animals.length; i += 2) {
  console.log(animals[i]);
}



    問題5：50以上の数値のみ表示
    for文バージョン
const scores = [45, 72, 88, 34, 60, 91, 50];

for (let i = 0; i < scores.length; i++) {
  if (scores[i] >= 50) {
    console.log(scores[i]);
  }
}
filter を使う方法（モダンな書き方）
const scores = [45, 72, 88, 34, 60, 91, 50];

const result = scores.filter(score => score >= 50);
console.log(result);

